const searchRides = `-- name: SearchRides :many
WITH ride_points AS (
    SELECT id as ride_id, origin as location, 0 as order_index
    FROM rides WHERE rides.status = 'active' AND rides.deleted_at IS NULL AND rides.available_seats >= $1
      AND rides.departure_time >= NOW() - INTERVAL '3 hours'
    UNION ALL
    SELECT id as ride_id, destination as location, 9999 as order_index
    FROM rides WHERE rides.status = 'active' AND rides.deleted_at IS NULL AND rides.available_seats >= $1
      AND rides.departure_time >= NOW() - INTERVAL '3 hours'
    UNION ALL
    SELECT rs.ride_id, rs.location, rs.order_index + 1
    FROM ride_stops rs
    INNER JOIN rides r ON r.id = rs.ride_id
    WHERE r.status = 'active' AND r.deleted_at IS NULL AND rs.deleted_at IS NULL AND r.available_seats >= $1
      AND r.departure_time >= NOW() - INTERVAL '3 hours'
)
SELECT DISTINCT 
    r.id, r.driver_id, r.vehicle_id, r.vehicle_data, ST_X(r.origin::geometry) as origin_lon, ST_Y(r.origin::geometry) as origin_lat, ST_X(r.destination::geometry) as dest_lon, ST_Y(r.destination::geometry) as dest_lat, r.origin_address, r.destination_address, r.departure_time, r.total_seats, r.available_seats, r.price_per_seat, r.gender_restriction, r.has_ac, r.has_luggage, r.takes_parcels, r.pickup_point, r.pickup_lat, r.pickup_lon, r.music_taste, r.no_smoking, r.no_pets, r.driving_speed, r.max_two_back, r.status, r.is_negotiable, r.has_fair_price_badge, r.allows_city_detour, r.city_detour_fee, r.cancel_reason, r.cancelled_at, r.created_at, r.updated_at
FROM rides r
INNER JOIN ride_points p1 ON r.id = p1.ride_id
INNER JOIN ride_points p2 ON r.id = p2.ride_id
WHERE p1.order_index < p2.order_index
  AND (
      (ST_DWithin(p1.location::geography, ST_SetSRID(ST_MakePoint($2, $3), 4326)::geography, $4)
       AND ST_DWithin(p2.location::geography, ST_SetSRID(ST_MakePoint($5, $6), 4326)::geography, $4))
      OR
      ($9::text = 'wait_at_route' 
       AND ST_Intersects(r.route_polygon, ST_SetSRID(ST_MakePoint($2, $3), 4326))
       AND ST_Intersects(r.route_polygon, ST_SetSRID(ST_MakePoint($5, $6), 4326)))
  )
  AND r.deleted_at IS NULL
  AND r.departure_time >= NOW() - INTERVAL '3 hours'
  AND ($10::boolean = true OR r.driver_id != '00000000-0000-0000-0000-000000000001'::uuid)
  AND (
      r.gender_restriction IS NULL 
      OR r.gender_restriction = ''
      OR r.gender_restriction = 'any'
      OR r.gender_restriction = $11::text
  )
  AND ($12::numeric IS NULL OR r.price_per_seat >= $12::numeric)
  AND ($13::numeric IS NULL OR r.price_per_seat <= $13::numeric)
  AND ($14::timestamptz IS NULL OR r.departure_time >= $14::timestamptz)
  AND ($15::timestamptz IS NULL OR r.departure_time <= $15::timestamptz)
ORDER BY r.has_fair_price_badge DESC, r.departure_time ASC
LIMIT $7 OFFSET $8
`

type SearchRidesParams struct {
	AvailableSeats   int32              `json:"available_seats"`
	StMakepoint      interface{}        `json:"st_makepoint"`
	StMakepoint_2    interface{}        `json:"st_makepoint_2"`
	StDwithin        interface{}        `json:"st_dwithin"`
	StMakepoint_3    interface{}        `json:"st_makepoint_3"`
	StMakepoint_4    interface{}        `json:"st_makepoint_4"`
	Limit            int32              `json:"limit"`
	Offset           int32              `json:"offset"`
	PickupPreference pgtype.Text        `json:"pickup_preference"`
	IncludeTest      pgtype.Bool        `json:"include_test"`
	PassengerGender  pgtype.Text        `json:"passenger_gender"`
	PriceMin         pgtype.Numeric     `json:"price_min"`
	PriceMax         pgtype.Numeric     `json:"price_max"`
	DateFrom         pgtype.Timestamptz `json:"date_from"`
	DateTo           pgtype.Timestamptz `json:"date_to"`
}

type SearchRidesRow struct {
	ID                 pgtype.UUID        `json:"id"`
	DriverID           pgtype.UUID        `json:"driver_id"`
	VehicleID          pgtype.UUID        `json:"vehicle_id"`
	VehicleData        []byte             `json:"vehicle_data"`
	OriginLon          interface{}        `json:"origin_lon"`
	OriginLat          interface{}        `json:"origin_lat"`
	DestLon            interface{}        `json:"dest_lon"`
	DestLat            interface{}        `json:"dest_lat"`
	OriginAddress      string             `json:"origin_address"`
	DestinationAddress string             `json:"destination_address"`
	DepartureTime      pgtype.Timestamptz `json:"departure_time"`
	TotalSeats         int32              `json:"total_seats"`
	AvailableSeats     int32              `json:"available_seats"`
	PricePerSeat       pgtype.Numeric     `json:"price_per_seat"`
	GenderRestriction  pgtype.Text        `json:"gender_restriction"`
	HasAc              bool               `json:"has_ac"`
	HasLuggage         bool               `json:"has_luggage"`
	TakesParcels       bool               `json:"takes_parcels"`
	PickupPoint        string             `json:"pickup_point"`
	PickupLat          pgtype.Float8      `json:"pickup_lat"`
	PickupLon          pgtype.Float8      `json:"pickup_lon"`
	MusicTaste         pgtype.Text        `json:"music_taste"`
	NoSmoking          bool               `json:"no_smoking"`
	NoPets             bool               `json:"no_pets"`
	DrivingSpeed       pgtype.Text        `json:"driving_speed"`
	MaxTwoBack         bool               `json:"max_two_back"`
	Status             string             `json:"status"`
	IsNegotiable       bool               `json:"is_negotiable"`
	HasFairPriceBadge  bool               `json:"has_fair_price_badge"`
	AllowsCityDetour   pgtype.Bool        `json:"allows_city_detour"`
	CityDetourFee      pgtype.Numeric     `json:"city_detour_fee"`
	CancelReason       pgtype.Text        `json:"cancel_reason"`
	CancelledAt        pgtype.Timestamptz `json:"cancelled_at"`
	CreatedAt          pgtype.Timestamptz `json:"created_at"`
	UpdatedAt          pgtype.Timestamptz `json:"updated_at"`
}

func (q *Queries) SearchRides(ctx context.Context, arg SearchRidesParams) ([]SearchRidesRow, error) {
	rows, err := q.db.Query(ctx, searchRides,
		arg.AvailableSeats,
		arg.StMakepoint,
		arg.StMakepoint_2,
		arg.StDwithin,
		arg.StMakepoint_3,
		arg.StMakepoint_4,
		arg.Limit,
		arg.Offset,
		arg.PickupPreference,
		arg.IncludeTest,
		arg.PassengerGender,
		arg.PriceMin,
		arg.PriceMax,
		arg.DateFrom,
		arg.DateTo,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchRidesRow
	for rows.Next() {
		var i SearchRidesRow
		if err := rows.Scan(
			&i.ID,
			&i.DriverID,
			&i.VehicleID,
			&i.VehicleData,
			&i.OriginLon,
			&i.OriginLat,
			&i.DestLon,
			&i.DestLat,
			&i.OriginAddress,
			&i.DestinationAddress,
			&i.DepartureTime,
			&i.TotalSeats,
			&i.AvailableSeats,
			&i.PricePerSeat,
			&i.GenderRestriction,
			&i.HasAc,
			&i.HasLuggage,
			&i.TakesParcels,
			&i.PickupPoint,
			&i.PickupLat,
			&i.PickupLon,
			&i.MusicTaste,
			&i.NoSmoking,
			&i.NoPets,
			&i.DrivingSpeed,
			&i.MaxTwoBack,
			&i.Status,
			&i.IsNegotiable,
			&i.HasFairPriceBadge,
			&i.AllowsCityDetour,
			&i.CityDetourFee,
			&i.CancelReason,
			&i.CancelledAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

